//! Interface strings for the languages that are not written inline:
//! (English text as it appears in the `t("…", "…")` calls, translation).
//! Terms follow the wording of Microsoft Excel in each language.
//!
//! The key is the English text exactly as the program sees it, so one key
//! has one translation per language even when it is used in two places.
//! An English text that needs two translations is looked up with
//! `t_ctx("context", …)` under the key `"context|English"`.
//! A string that reads the same as in English is still listed, which lets
//! `python3 scripts/check_i18n.py` tell a finished table from a forgotten
//! string: it reports the keys that are missing, unused or duplicated.
//! The three tables list the same keys in the same order.

